// Generated from CRM_Address_Master.xlsx (ISO 3166) — do not edit the data blocks by hand.
// 249 countries, 5046 subdivisions.
//
// ISO 3166 address master (countries + ISO 3166-2 subdivisions) and lookup helpers.
// Countries are stored/compared by ISO 3166-1 alpha-2 code; names are for display.

export interface CountryMasterItem {
    countryName: string;
    /** ISO 3166-1 alpha-2 (e.g. 'IN', 'US', 'GB', 'NA' for Namibia). */
    iso2Code: string;
    /** ISO 3166-1 alpha-3 (e.g. 'IND', 'USA'). */
    iso3Code: string;
    numericCode: number;
}

export interface StateRegionMasterItem {
    countryName: string;
    /** Foreign key to CountryMasterItem.iso2Code. */
    countryIso2: string;
    /** ISO 3166-2 code (e.g. 'IN-DL', 'US-CA'). */
    subdivisionCode: string;
    /** Display name (e.g. 'Delhi', 'California'). */
    subdivisionName: string;
    /** e.g. 'State', 'Union territory', 'Province'. */
    subdivisionType: string;
}

export const DEFAULT_COUNTRY_CODE = 'IN';
export const DEFAULT_COUNTRY_NAME = 'India';
/** Appended to every state list so users can fall back to manual entry (Address_Field_Design: state_region). */
export const STATE_NOT_LISTED = 'Not listed';

