// ── Master tables ─────────────────────────────────────────────────────────────

/** All countries in ISO list order (alphabetical by name). */
export const COUNTRY_MASTER: readonly CountryMasterItem[] = COUNTRY_ROWS.map(
    ([countryName, iso2Code, iso3Code, numericCode]) => ({ countryName, iso2Code, iso3Code, numericCode })
);

const COUNTRY_BY_ISO2 = new Map(COUNTRY_MASTER.map((c) => [c.iso2Code, c]));

/** Countries for dropdowns: India first, then the rest alphabetically. */
export const COUNTRY_OPTIONS: readonly CountryMasterItem[] = [
    ...COUNTRY_MASTER.filter((c) => c.iso2Code === DEFAULT_COUNTRY_CODE),
    ...COUNTRY_MASTER.filter((c) => c.iso2Code !== DEFAULT_COUNTRY_CODE),
];

export const STATE_REGION_MASTER: readonly StateRegionMasterItem[] = SUBDIVISION_ROWS.map(
    ([countryIso2, subdivisionCode, subdivisionName, typeIdx]) => ({
        countryName: COUNTRY_BY_ISO2.get(countryIso2)?.countryName ?? '',
        countryIso2,
        subdivisionCode,
        subdivisionName,
        subdivisionType: SUBDIVISION_TYPES[typeIdx] ?? '',
    })
);

// ── Normalisation ─────────────────────────────────────────────────────────────

/**
 * Diacritic/case/punctuation-insensitive key: 'Haryāna' → 'haryana', 'Jammu & Kashmir' → 'jammu and kashmir'.
 * Use it for search matching so ASCII input finds ISO names with diacritics.
 */
export function normalizeSearchText(text?: string | null): string {
    return (text ?? '')
        .normalize('NFD')
        .replace(/[̀-ͯ]/g, '')
        .toLowerCase()
        .replace(/&/g, ' and ')
        .replace(/[^a-z0-9]+/g, ' ')
        .trim();
}

/** Strips diacritics but keeps case and punctuation: 'Haryāna' → 'Haryana', 'Jammu and Kashmīr' → 'Jammu and Kashmir'. */
export function toPlainName(text: string): string {
    return text.normalize('NFD').replace(/[̀-ͯ]/g, '');
}

/** True when `option` contains `query`, ignoring case and diacritics. */
export function matchesSearch(option: string, query: string): boolean {
    return normalizeSearchText(option).includes(normalizeSearchText(query));
}

